-- ======================== -- SCHEMA: storage -- ======================== -- storage.buckets (rows ~0) CREATE TABLE IF NOT EXISTS storage.buckets ( id text PRIMARY KEY, name text, owner uuid, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), public boolean DEFAULT false, avif_autodetection boolean DEFAULT false, file_size_limit bigint, allowed_mime_types text[], owner_id text, type storage.buckettype DEFAULT 'STANDARD'::storage.buckettype ); COMMENT ON TABLE storage.buckets IS 'Storage: buckets';

CREATE TABLE IF NOT EXISTS storage.objects ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), bucket_id text, name text, owner uuid, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), last_accessed_at timestamptz DEFAULT now(), metadata jsonb, path_tokens text[] GENERATED ALWAYS AS (string_to_array(name, '/'::text)) STORED, version text, owner_id text, user_metadata jsonb, level integer ); -- (Other storage tables: s3_multipart_uploads, s3_multipart_uploads_parts, prefixes, buckets_analytics, buckets_vectors, vector_indexes)

-- ======================== -- SCHEMA: public -- ======================== -- Table: public.users (app user profile) (rows ~64) CREATE TABLE IF NOT EXISTS public.users ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE, name text, profile_picture_url text, section text CHECK (section IS NULL OR section ~ '^[A-Z][1-4]$' OR section ~ '^(ML|DS|CS)[1-4]$'), year integer CHECK (year >= 1 AND year <= 4), skills text[] DEFAULT '{}'::text[], github_url text, linkedin_url text, social_visibility text DEFAULT 'on_application' CHECK (social_visibility = ANY (ARRAY['always','on_application','hidden'])), gehu_verified boolean DEFAULT false, gehu_email text UNIQUE, role text DEFAULT 'student' CHECK (role = ANY (ARRAY['student','moderator','super_admin','event_manager','god'])), is_banned boolean DEFAULT false, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), search_vector tsvector, gender gender_enum DEFAULT 'prefer_not_to_say'::gender_enum );

-- Table: public.chatrooms (rows ~119) CREATE TABLE IF NOT EXISTS public.chatrooms ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type text CHECK (type = ANY (ARRAY['dm','team','recruitment','group'])), team_id uuid, recruitment_post_id uuid, name text, created_at timestamptz DEFAULT now(), archived boolean DEFAULT false );

-- Table: public.chatroom_members (rows ~152) CREATE TABLE IF NOT EXISTS public.chatroom_members ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), chatroom_id uuid, user_id uuid, joined_at timestamptz DEFAULT now(), last_read_at timestamptz DEFAULT now() ); ALTER TABLE public.chatroom_members ADD CONSTRAINT chatroom_members_chatroom_id_fkey FOREIGN KEY (chatroom_id) REFERENCES public.chatrooms(id);

-- Table: public.messages (rows ~13) CREATE TABLE IF NOT EXISTS public.messages ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), chatroom_id uuid, sender_id uuid, content text, created_at timestamptz DEFAULT now(), edited_at timestamptz, deleted boolean DEFAULT false, reply_to_message_id uuid, forwarded_from_message_id uuid ); ALTER TABLE public.messages ADD CONSTRAINT messages_chatroom_id_fkey FOREIGN KEY (chatroom_id) REFERENCES public.chatrooms(id); ALTER TABLE public.messages ADD CONSTRAINT messages_sender_id_fkey FOREIGN KEY (sender_id) REFERENCES public.users(id);

-- Table: public.notifications (rows ~6) CREATE TABLE IF NOT EXISTS public.notifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, type text CHECK (type = ANY (ARRAY['application','team_invite','message','system','event'])), title text, message text, link text, read boolean DEFAULT false, created_at timestamptz DEFAULT now(), read_at timestamptz );

