-- Example: Contacts ALTER TABLE public.contacts ENABLE ROW LEVEL SECURITY; CREATE POLICY "Contacts select" ON public.contacts FOR SELECT TO public USING (owner_id = auth.uid()); CREATE POLICY "Contacts manage" ON public.contacts FOR ALL TO public USING (owner_id = auth.uid()) WITH CHECK (owner_id = auth.uid());

-- Friend requests ALTER TABLE public.friend_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY "Friend requests select" ON public.friend_requests FOR SELECT TO public USING ((sender_id = auth.uid()) OR (receiver_id = auth.uid())); CREATE POLICY "Friend requests insert" ON public.friend_requests FOR INSERT TO public WITH CHECK (sender_id = auth.uid()); CREATE POLICY "Friend requests update" ON public.friend_requests FOR UPDATE TO public USING ((sender_id = auth.uid()) OR (receiver_id = auth.uid())) WITH CHECK ((sender_id = auth.uid()) OR (receiver_id = auth.uid())); CREATE POLICY "Friend requests delete" ON public.friend_requests FOR DELETE TO public USING (sender_id = auth.uid());

-- Teams (view/create/update rules) ALTER TABLE public.teams ENABLE ROW LEVEL SECURITY; CREATE POLICY "Anyone can view teams" ON public.teams FOR SELECT TO public USING (true); CREATE POLICY "Leaders can update teams" ON public.teams FOR UPDATE TO public USING (leader_id = auth.uid()); CREATE POLICY "Verified users can create teams" ON public.teams FOR INSERT TO public WITH CHECK ((EXISTS ( SELECT 1 FROM public.users WHERE ((users.id = auth.uid()) AND (users.gehu_verified = true)))));

-- Chatroom related policies (members, messages, roles, mutes) ALTER TABLE public.chatrooms ENABLE ROW LEVEL SECURITY; ALTER TABLE public.chatroom_members ENABLE ROW LEVEL SECURITY; ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY; ALTER TABLE public.chatroom_roles ENABLE ROW LEVEL SECURITY; ALTER TABLE public.chatroom_mutes ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Members can view chatrooms" ON public.chatrooms FOR SELECT TO public USING (EXISTS ( SELECT 1 FROM public.chatroom_members WHERE ((chatroom_members.chatroom_id = chatrooms.id) AND (chatroom_members.user_id = auth.uid())))); CREATE POLICY "Chat members add self" ON public.chatroom_members FOR INSERT TO public WITH CHECK (user_id = auth.uid()); CREATE POLICY "Users view own memberships" ON public.chatroom_members FOR SELECT TO public USING (user_id = auth.uid()); CREATE POLICY "Chat managers invite members" ON public.chatroom_members FOR INSERT TO public WITH CHECK (can_manage_chatroom_members(chatroom_id)); CREATE POLICY "Chat managers update members" ON public.chatroom_members FOR UPDATE TO public USING (can_manage_chatroom_members(chatroom_id)) WITH CHECK (can_manage_chatroom_members(chatroom_id)); CREATE POLICY "Chat managers remove members" ON public.chatroom_members FOR DELETE TO public USING (can_manage_chatroom_members(chatroom_id) OR (user_id = auth.uid()));

CREATE POLICY "Members can view messages" ON public.messages FOR SELECT TO public USING (EXISTS ( SELECT 1 FROM public.chatroom_members WHERE ((chatroom_members.chatroom_id = messages.chatroom_id) AND (chatroom_members.user_id = auth.uid())))); CREATE POLICY "Members can send messages" ON public.messages FOR INSERT TO public WITH CHECK ((sender_id = auth.uid()) AND (EXISTS ( SELECT 1 FROM public.chatroom_members WHERE ((chatroom_members.chatroom_id = messages.chatroom_id) AND (chatroom_members.user_id = auth.uid())))));

-- Notifications ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users view own notifications" ON public.notifications FOR SELECT TO public USING (user_id = auth.uid()); CREATE POLICY "Users update own notifications" ON public.notifications FOR UPDATE TO public USING (user_id = auth.uid());

